@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Space+Grotesk:wght@400;500;600;700&display=swap');
:root{color-scheme:dark;--ink:#f6f1dc;--muted:#a8b2b4;--gold:#e8bc69;--line:#34444d;--panel:#172634;--mint:#97d7b6}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:radial-gradient(ellipse at 50% 20%,#263849 0,#111d2a 52%,#0b1420 100%);color:var(--ink);font-family:'Space Grotesk',sans-serif;display:flex;align-items:center;justify-content:center;padding:24px 16px}.shell{width:min(100%,1000px)}.topbar{height:56px;display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.brand{display:flex;align-items:center;gap:12px;letter-spacing:.13em}.brand-icon{font-size:27px;color:var(--gold);text-shadow:0 0 15px #e8bc6980}.brand b{font-size:13px;display:block}.brand small{font:9px 'DM Mono',monospace;color:#93a1a6;letter-spacing:.18em}.top-right{display:flex;align-items:center;gap:12px}.pixel-tag{font:10px 'DM Mono',monospace;color:#c5d0ce;border:1px solid #485b63;padding:7px 10px;letter-spacing:.1em}.icon-btn,.panel-close{border:1px solid #53656c;background:#1a2a36;color:var(--ink);width:29px;height:29px;cursor:pointer;font-weight:bold}.game-frame{position:relative;width:100%;aspect-ratio:16/9;overflow:hidden;border:1px solid #53626a;box-shadow:0 18px 65px #0008,0 0 0 5px #172532;background:#243d3c}canvas{width:100%;height:100%;display:block;image-rendering:pixelated;image-rendering:crisp-edges;cursor:crosshair}.hud-top{position:absolute;inset:12px 14px auto;display:flex;justify-content:space-between;pointer-events:none}.hud-chip{height:27px;padding:0 10px;display:flex;align-items:center;gap:8px;background:#10202bd9;border:1px solid #ffffff27;color:#f5e8c1;font:10px 'DM Mono',monospace;letter-spacing:.1em}.hud-chip>span:first-child{color:#ee7d70;font-size:15px}.health-track{width:86px;height:7px;background:#482f36}.health-track i{height:100%;display:block;width:100%;background:#df786d;transition:width .2s}.day-chip{color:#f3cf83}.hud-bottom{position:absolute;inset:auto 0 0;min-height:38px;display:flex;align-items:center;gap:7px;padding:5px 12px;background:linear-gradient(0deg,#101d28ed,#101d28bf);border-top:1px solid #ffffff1b}.location{margin-right:auto;display:flex;align-items:center;gap:7px;font:9px 'DM Mono',monospace;letter-spacing:.1em;color:#e0e6d9}.location i{width:6px;height:6px;background:#91d6ad;box-shadow:0 0 9px #91d6ad;border-radius:50%}.small-button{background:#223541;border:1px solid #52646b;color:#f3edda;padding:6px 9px;font:9px 'DM Mono',monospace;cursor:pointer}.small-button:hover,.icon-btn:hover{border-color:var(--gold);color:var(--gold)}kbd{color:#a7b2b1;font-size:8px;margin-left:4px}.objective{position:absolute;right:13px;top:50px;width:min(240px,40%);background:#12232ddd;border:1px solid #ffffff23;padding:9px 11px;display:flex;align-items:center;gap:10px;box-shadow:0 4px 15px #0003}.objective-mark{color:var(--gold);font-size:17px}.objective small{display:block;color:#aab8b6;font:8px 'DM Mono',monospace;letter-spacing:.15em;margin-bottom:4px}.objective b{font-size:11px;font-weight:600;line-height:1.25;display:block}.toast{position:absolute;left:50%;top:23%;transform:translate(-50%,-6px);background:#10232dec;border:1px solid #e8bc6970;padding:8px 13px;color:#ffe4a6;font:10px 'DM Mono',monospace;opacity:0;transition:.2s;pointer-events:none;white-space:nowrap;z-index:5}.toast.show{opacity:1;transform:translate(-50%,0)}.interact-hint{position:absolute;left:50%;bottom:52px;transform:translateX(-50%);background:#101d28bd;color:#f3e5b9;padding:5px 9px;font:9px 'DM Mono',monospace;letter-spacing:.08em;opacity:0;pointer-events:none}.interact-hint.show{opacity:1}.dialogue{position:absolute;left:5%;right:5%;bottom:8%;min-height:68px;background:#122231f2;border:1px solid #c69f61;padding:13px 18px 12px;box-shadow:0 8px 30px #0009;z-index:7}.dialogue.hidden{display:none}.speaker{font:9px 'DM Mono',monospace;letter-spacing:.18em;color:var(--gold);margin-bottom:6px}.dialogue #dialogueText{font-size:13px;line-height:1.4;padding-right:98px}.dialogue-next{position:absolute;right:12px;bottom:12px;border:0;background:transparent;color:#ecd294;font:9px 'DM Mono',monospace;cursor:pointer}.dialogue-next span{padding-left:6px}.screen-overlay{position:absolute;inset:0;display:grid;place-items:center;background:linear-gradient(90deg,#0b1720df,#13252ad9 55%,#0c1826df);z-index:10}.screen-overlay.hidden,.panel.hidden{display:none}.start-card{width:min(450px,82%);text-align:center;padding:22px;background:#101e2ddd;border:1px solid #d0aa6177;box-shadow:0 14px 40px #0008}.eyebrow{font:9px 'DM Mono',monospace;letter-spacing:.22em;color:#d9bd7d}.start-card h1{font-size:43px;line-height:.9;letter-spacing:.08em;margin:15px 0 12px}.start-card h1 em{font-style:normal;color:var(--gold)}.start-card p{color:#c7d0ca;font-size:13px;line-height:1.55}.primary-button{background:#d7ad62;color:#15232b;border:0;padding:11px 18px;margin:9px 0 7px;font:700 11px 'DM Mono',monospace;letter-spacing:.07em;cursor:pointer;box-shadow:0 3px 0 #967441}.primary-button:hover{background:#f0ca7a;transform:translateY(-1px)}.controls-note{color:#9eacae;font:8px 'DM Mono',monospace;margin-top:8px;letter-spacing:.04em}.panel{position:absolute;z-index:8;inset:12% 18%;background:#142532f5;border:1px solid #d0aa61b0;padding:18px 20px;box-shadow:0 15px 50px #000c;overflow:auto}.panel-close{position:absolute;right:12px;top:12px;font-size:19px;border:0;background:transparent}.panel h2{margin:0;color:#f1d392;letter-spacing:.12em;font-size:16px}.panel-sub{font-size:11px;color:#aab8b6;margin:5px 0 15px}.inventory-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:7px}.item-slot{min-height:43px;border:1px solid #41545c;background:#1e303b;padding:7px;font:10px 'DM Mono',monospace;color:#e8e4d7}.item-slot b{float:right;color:#f2cc7c;font-size:12px}.stats-line{border-top:1px solid #3b5058;margin-top:12px;padding-top:10px;color:#aebcba;font:9px 'DM Mono',monospace}.recipe-list{display:grid;gap:8px}.recipe{border:1px solid #455960;padding:10px;display:flex;align-items:center;justify-content:space-between;background:#1b2c37}.recipe b{font-size:12px}.recipe small{display:block;color:#aab7b4;font:9px 'DM Mono',monospace;margin-top:4px}.recipe button{border:1px solid #d4ae6a;background:#d4ae6a;color:#14232a;padding:7px 10px;font:9px 'DM Mono',monospace;cursor:pointer}.recipe button:disabled{background:#34464e;border-color:#45555b;color:#899597;cursor:not-allowed}.recipe-note{font:9px 'DM Mono',monospace;color:#9eb0ad;margin-top:10px}.ending-card{background:#10202deF}.ending-card p{font-size:16px;color:#f3d996}.ending-stat{font:9px 'DM Mono',monospace;color:#aebdb9;margin:12px}.footer{height:35px;display:flex;justify-content:space-between;align-items:end;color:#8b9b9d;font:8px 'DM Mono',monospace;letter-spacing:.1em}.footer i{font-style:normal;color:var(--gold);padding-left:5px}.footer b{color:#d7b669;padding:0 4px}.touch-controls{display:none}.touch-controls button{touch-action:none}.dpad{display:grid;gap:2px}.dpad button,.touch-action{height:38px;min-width:40px;border:1px solid #d4c17e77;background:#112430d9;color:#f1d28b;font-size:16px}.dpad>button{justify-self:center}.dpad div{display:flex;gap:2px}.touch-action{width:50px;height:50px;border-radius:50%;font-size:21px}
@media(max-width:650px){body{padding:10px 8px;align-items:flex-start}.topbar{height:42px;margin-bottom:8px}.brand b{font-size:11px}.brand small{font-size:7px}.brand-icon{font-size:21px}.pixel-tag{font-size:8px;padding:6px}.game-frame{margin-top:5px;aspect-ratio:16/10}.hud-top{inset:7px 7px auto}.hud-chip{height:23px;padding:0 6px;font-size:8px}.health-track{width:53px}.objective{top:37px;right:7px;width:175px;padding:6px;font-size:10px}.objective b{font-size:9px}.hud-bottom{padding:4px 6px;gap:4px;min-height:31px}.location{font-size:7px;letter-spacing:0}.small-button{font-size:7px;padding:5px 5px}.small-button kbd{display:none}.dialogue{left:3%;right:3%;bottom:5%;padding:10px 12px;min-height:64px}.dialogue #dialogueText{font-size:11px}.dialogue-next{font-size:8px;bottom:7px;right:5px}.start-card{padding:17px;width:90%}.start-card h1{font-size:34px;margin:10px}.start-card p{font-size:11px;margin:8px}.primary-button{font-size:9px;padding:10px 12px}.controls-note{font-size:7px}.panel{inset:8% 5%;padding:16px}.inventory-grid{grid-template-columns:repeat(3,1fr)}.footer{font-size:6px;letter-spacing:0}.touch-controls{display:flex;position:fixed;left:13px;right:13px;bottom:11px;justify-content:space-between;align-items:end;z-index:15;opacity:.85;pointer-events:none}.touch-controls button{pointer-events:auto}.dpad,.touch-action{filter:drop-shadow(0 3px 4px #0008)}.interact-hint{bottom:42px}.objective{display:none}.ending-card{width:90%}}

(() => {
  'use strict';
  const canvas = document.getElementById('game'), ctx = canvas.getContext('2d');
  ctx.imageSmoothingEnabled = false;
  const W=canvas.width,H=canvas.height, world={w:1500,h:960};
  const $=id=>document.getElementById(id);
  const ui={toast:$('toast'),dialogue:$('dialogue'),dialogueText:$('dialogueText'),speaker:$('speaker'),objective:$('objectiveText'),hint:$('interactHint'),health:$('healthFill'),day:$('dayLabel'),loc:$('locationLabel'),inventory:$('inventoryPanel'),craft:$('craftPanel'),start:$('startScreen'),ending:$('endingScreen')};
  const items={wood:0,stone:0,berry:0,meat:0,ore:0,plank:0,workbench:0,house:0,sword:0,key:0};
  const player={x:82,y:105,hp:6,maxHp:6,speed:82,dir:1,walked:0,attackAt:0,invuln:0};
  let started=false,mode='intro',introIndex=0,dialogueDone=null,dialogueLines=[], tutorialStep=0, gameTime=0, days=1,toastTimer=0,anim=0,lastFrame=0,moveKeys={},touchDirs={},camera={x:0,y:0},clickBuffer={entity:null,time:0}, boss=null, bossDefeated=false,villageFound=false,castleFound=false,ending=false;
  let entities=[];
  const mk=(type,x,y,extra={})=>({type,x,y,hp:extra.hp??1,maxHp:extra.hp??1,alive:true,...extra});
  const addWorld=()=>{
    entities=[];
    [[175,116],[260,240],[410,110],[485,350],[690,180],[835,430],[1160,210],[1260,680],[910,760],[340,700],[590,555]].forEach(([x,y])=>entities.push(mk('tree',x,y,{hp:4})));
    [[210,185],[350,340],[560,245],[760,590],[980,175],[1140,730],[1320,310],[500,810]].forEach(([x,y])=>entities.push(mk('rock',x,y,{hp:3})));
    [[330,160],[500,470],[780,290],[1050,640],[1250,440]].forEach(([x,y])=>entities.push(mk('ore',x,y,{hp:4})));
    [[130,160],[290,105],[450,255],[650,450],[875,195],[960,520],[1200,350]].forEach(([x,y])=>entities.push(mk('berry',x,y,{hp:1,ready:true,clicks:0})));
    [[118,220],[300,280],[520,115],[720,390],[900,300],[1100,560],[1290,610]].forEach(([x,y],i)=>entities.push(mk(i%2?'wisp':'slime',x,y,{hp:i<2?3:4,maxHp:i<2?3:4,homeX:x,homeY:y,phase:i*1.7,aggro:false})));
    entities.push(mk('village',1040,270,{name:'Vila dos Cogumelos'}));
    entities.push(mk('castle',1380,500,{name:'Castelo do Rei Demônio'}));
  };
  addWorld();
  function say(text,duration=2100){ui.toast.textContent=text;ui.toast.classList.add('show');toastTimer=duration;}
  function setObjective(text){ui.objective.textContent=text;}
  function openDialogue(speaker,texts,onDone){dialogueLines=texts;introIndex=0;dialogueDone=onDone||null;ui.speaker.textContent=speaker;ui.dialogueText.textContent=texts[0];ui.dialogue.classList.remove('hidden');}
  function nextDialogue(){if(ui.dialogue.classList.contains('hidden'))return;if(introIndex<dialogueLines.length-1){introIndex++;ui.dialogueText.textContent=dialogueLines[introIndex];}else{ui.dialogue.classList.add('hidden');const cb=dialogueDone;dialogueDone=null;if(cb)cb();}}
  function startGame(){if(started)return;started=true;ui.start.classList.add('hidden');mode='intro';openDialogue('NARRADOR',["Depois de um longo dia, você coloca seu novo óculos de realidade virtual.","Uma luz azul preenche tudo. O quarto desaparece — e um vento frio sopra no seu rosto.","Você desperta num prado encantado, cercado por ruínas medievais e criaturas mágicas.","ENZO: Oh meu Deus... onde que eu fui parar!"],()=>beginTutorial());}
  function beginTutorial(){mode='tutorial';tutorialStep=0;setObjective('Aprenda a se mover: use WASD ou as setas.');say('TUTORIAL · MOVA-SE PELO PRADO',2200);}
  function finishTutorial(){mode='survival';tutorialStep=3;setObjective('Construa um lar: reúna madeira e pedra.');openDialogue('ENZO',["Ufa! Essas criaturas deixam carne... e eu vou precisar de abrigo.","Agora começa a aventura de verdade. Junte recursos, construa e descubra este mundo.","Dizem que há uma vila ao leste... e um castelo sombrio além dela."],()=>say('TUTORIAL CONCLUÍDO · SUA AVENTURA COMEÇA!',2600));}
  function startEnding(){if(ending)return;ending=true;mode='ending';openDialogue('NARRADOR',["Com um último golpe, o Rei Demônio cai. O castelo inteiro estremece.","Entre os destroços, você encontra uma chave dourada. A porta atrás do trono se abre.","Uma luz familiar envolve você. O visor se desprende — seu quarto está de volta.","ENZO: O meu Deus, finalmente estou aqui de novo!"],()=>{ui.ending.classList.remove('hidden');$('endingStats').textContent=`DIA ${days}  ·  CASA ${items.house?'CONSTRUÍDA':'NÃO CONSTRUÍDA'}  ·  VILA ${villageFound?'DESCOBERTA':'NÃO DESCOBERTA'}`;});}
  function distance(a,b){return Math.hypot(a.x-b.x,a.y-b.y);}
  function nearestEntity(max=40,types=null){let best=null,d=max;for(const e of entities){if(!e.alive||types&&!types.includes(e.type))continue;const n=distance(player,e);if(n<d){best=e;d=n;}}return best;}
  function give(name,n=1){items[name]=(items[name]||0)+n;updatePanels();}
  function updatePanels(){
    const names={wood:'木 Madeira',stone:'◈ Pedra',berry:'✿ Frutas',meat:'◆ Carne',ore:'⬡ Minério',plank:'▤ Tábuas',workbench:'⚒ Bancada',house:'⌂ Casa',sword:'⚔ Espada',key:'⚿ Chave'};
    $('inventoryGrid').innerHTML=Object.entries(names).map(([k,v])=>`<div class="item-slot">${v}<b>${items[k]||0}</b></div>`).join('');
    $('statsLine').textContent=`VIDA ${player.hp}/${player.maxHp}  ·  DIA ${days}  ·  ${villageFound?'VILA DESCOBERTA':'VILA NÃO ENCONTRADA'}`;
    const recipes=[['workbench','Bancada de trabalho','8 madeira · 4 pedra',()=>items.wood>=8&&items.stone>=4,()=>{items.wood-=8;items.stone-=4;items.workbench++;say('BANCADA CONSTRUÍDA!');}],['house','Casa de madeira','15 madeira · 5 pedra · bancada',()=>items.wood>=15&&items.stone>=5&&items.workbench>0,()=>{items.wood-=15;items.stone-=5;items.house++;player.maxHp=8;player.hp=8;say('SUA CASA ESTÁ PRONTA · VIDA MÁXIMA AUMENTOU!');}],['sword','Espada de ferro','5 minério · 3 madeira · bancada',()=>items.ore>=5&&items.wood>=3&&items.workbench>0,()=>{items.ore-=5;items.wood-=3;items.sword++;say('ESPADA FORJADA · ATAQUE MAIS FORTE!');}]];
    $('recipeList').innerHTML=recipes.map(([key,title,cost,can,craft])=>`<div class="recipe"><div><b>${title}${items[key]?' ✓':''}</b><small>${cost}</small></div><button data-recipe="${key}" ${can()?'':'disabled'}>${items[key]?'CONSTRUÍDO':'CRIAR'}</button></div>`).join('')+'<div class="recipe-note">Dica: clique em árvores 4 vezes, pedras 3 vezes e minério 4 vezes. Clique duas vezes nas frutas.</div>';
    $('recipeList').querySelectorAll('[data-recipe]').forEach(btn=>btn.onclick=()=>{const r=recipes.find(x=>x[0]===btn.dataset.recipe);if(r&&r[3]()){r[4]();updatePanels();checkProgress();}});
  }
  function updateHealth(){ui.health.style.width=`${Math.max(0,player.hp/player.maxHp*100)}%`;updatePanels();}
  function target(e){if(!e||!e.alive)return;const now=performance.now();
    if(distance(player,e)>36){ui.hint.textContent='CHEGUE MAIS PERTO';ui.hint.classList.add('show');say('Chegue mais perto para interagir.');return;}
    ui.hint.classList.remove('show');
    if(e.type==='tree'||e.type==='rock'||e.type==='ore'){
      e.hp--;const left=e.hp;
      if(left<=0){e.alive=false;const resource={tree:['wood',3],rock:['stone',2],ore:['ore',2]}[e.type];give(resource[0],resource[1]);say(`${resource[1]} ${resource[0]==='wood'?'MADEIRA':resource[0]==='stone'?'PEDRA':'MINÉRIO'} COLETADA!`);if(mode==='tutorial'&&e===tutorialTree){tutorialStep=2;setObjective('Agora derrote a criatura mágica e pegue comida.');say('ÁRVORE QUEBRADA · +3 MADEIRA');}checkProgress();}
      else say(`${e.type==='tree'?'ÁRVORE':e.type==='rock'?'PEDRA':'MINÉRIO'} · ${left} TOQUES RESTANTES`);
      anim=8;return;
    }
    if(e.type==='berry'){
      if(now-clickBuffer.time<650&&clickBuffer.entity===e){give('berry',2);e.alive=false;clickBuffer={entity:null,time:0};say('FRUTAS SILVESTRES COLETADAS · +2');}
      else{clickBuffer={entity:e,time:now};say('MAIS UM CLIQUE PARA COLHER');}return;
    }
    if(e.type==='slime'||e.type==='wisp'||e.type==='demon'){
      if(e.type==='demon'&&!items.sword){say('SUA ARMA NÃO É FORTE O BASTANTE · FORJE UMA ESPADA!');return;}
      if(now-player.attackAt<350)return;player.attackAt=now;const damage=items.sword?2:1;e.hp-=damage;anim=12;
      if(e.hp<=0){e.alive=false;if(e.type==='demon'){bossDefeated=true;items.key=1;say('REI DEMÔNIO DERROTADO · PEGUE A CHAVE!');openDialogue('ENZO',["Consegui! O rei demônio foi derrotado!","A chave... ela deve abrir aquela porta!"],()=>{setObjective('Pegue a chave dourada no castelo.');});}
        else{give('meat',1);say('CRIATURA DERROTADA · +1 CARNE');if(mode==='tutorial'&&e===tutorialSlime){tutorialStep=3;finishTutorial();}checkProgress();}}
      else say(`${e.type==='demon'?'REI DEMÔNIO':e.type==='wisp'?'FADA SOMBRIA':'SLIME'} · ${e.hp} VIDA`);return;
    }
    if(e.type==='village'){if(!villageFound){villageFound=true;say('VILA DOS COGUMELOS DESCOBERTA!');openDialogue('MORADORA DA VILA',["Seja bem-vindo, viajante! O castelo do Rei Demônio fica a oeste das montanhas.","Você pode ficar por aqui... mas cuidado com as criaturas da noite."],()=>checkProgress());}else say('VILA DOS COGUMELOS · UM LUGAR PARA CHAMAR DE LAR');}
    if(e.type==='castle'){
      if(!castleFound){castleFound=true;openDialogue('ENZO',["O Castelo do Rei Demônio! É aqui que tudo termina.","Mas preciso de uma espada de ferro antes de entrar."],()=>checkProgress());}
      else if(bossDefeated&&items.key){openDialogue('ENZO',["A chave dourada! A porta está se abrindo..."],()=>startEnding());}
      else if(!boss){boss=mk('demon',e.x-35,e.y-5,{hp:12,maxHp:12});entities.push(boss);setObjective('Derrote o Rei Demônio com sua espada.');say('O REI DEMÔNIO APARECE!');}
      else say('DERROTE O REI DEMÔNIO E PEGUE A CHAVE.');
    }
  }
  let tutorialTree,tutorialSlime;
  function checkProgress(){if(mode==='survival'){
    if(!items.workbench)setObjective('Reúna 8 madeira e 4 pedra para uma bancada.');
    else if(!items.house)setObjective('Construa sua casa: 15 madeira e 5 pedra.');
    else if(!villageFound)setObjective('Explore o mundo e encontre a Vila dos Cogumelos.');
    else if(!items.sword)setObjective('Minere 5 ferros e crie uma espada na bancada.');
    else if(!bossDefeated)setObjective('Vá ao Castelo do Rei Demônio e derrote-o.');
    else if(items.key)setObjective('Use a chave dourada na porta do castelo!');
  }}
  tutorialTree=entities.find(e=>e.type==='tree'&&e.x===175);tutorialSlime=entities.find(e=>e.type==='slime'&&e.x===118);
  function actNearest(){const e=nearestEntity(52,['tree','rock','ore','berry','slime','wisp','demon','village','castle']);if(e)target(e);else say('Não há nada por perto para interagir.');}
  function entityAt(wx,wy){let best=null,bd=19;for(const e of entities){if(!e.alive)continue;const r=e.type==='tree'?19:e.type==='village'?26:e.type==='castle'?30:e.type==='demon'?20:13;const d=Math.hypot(e.x-wx,e.y-wy);if(d<r&&d<bd){best=e;bd=d;}}return best;}
  function handleCanvasClick(ev){if(!started||!ui.dialogue.classList.contains('hidden')||mode==='ending')return;const rect=canvas.getBoundingClientRect(),sx=canvas.width/rect.width,sy=canvas.height/rect.height;const px=(ev.clientX-rect.left)*sx,py=(ev.clientY-rect.top)*sy;const e=entityAt(px+camera.x,py+camera.y);if(e)target(e);else actNearest();}
  canvas.addEventListener('pointerdown',handleCanvasClick);

  function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),w,h);}
  function text(t,x,y,color='#e9e4ca',size=6,align='left'){ctx.fillStyle=color;ctx.font=`${size}px monospace`;ctx.textAlign=align;ctx.fillText(t,Math.round(x),Math.round(y));ctx.textAlign='left';}
  function drawTree(x,y){rect(x-9,y-2,18,8,'#674b35');rect(x-13,y-17,26,17,'#315c43');rect(x-10,y-23,20,12,'#42764d');rect(x-5,y-27,10,7,'#59865a');rect(x-8,y-9,5,4,'#68905a');rect(x+5,y-18,5,4,'#588452');rect(x-2,y-2,4,8,'#96704a');}
